#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: carrega o banco de produção (Supabase) com os dados do Postgres local, em vez de reconstruir pelo ETL (D252).
# Só dados: o schema vem de db/migrate.sh, e as migrações aplicadas têm de ser as mesmas dos dois lados (checksum).
# Tabelas de usuário (perfis, follows, sugestões, page views) e o estado da agenda não saem do local.
# Produção tem de estar vazia, salvo o seed: se o ETL já escreveu lá, o assistente para.
# Uma transação com BEGIN explícito; o COMMIT só é enviado se o pg_restore terminou e se, dentro da própria transação,
# as contagens batem com o snapshot local e nenhuma FK ficou órfã. Qualquer outra saída (erro, Ctrl-C, queda) desfaz.
# A URL de produção não vai para argv, arquivo nem para o ambiente do shell: só para o ambiente de cada psql de produção.
# Uso: etl/deploy/prod-restore.sh   (do Mac, com o Postgres local de pé e `gh auth login` feito)
# Teste local: ALLOW_LOCAL_TARGET=1 SKIP_GH=1 ONLY_TABLES="places parties" etl/deploy/prod-restore.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
MAIN="$(cd "$(git -C "$ROOT" rev-parse --path-format=absolute --git-common-dir)/.." && pwd)"
PY="$ROOT/etl/.venv/bin/python"
export GH_REPO="${GH_REPO:-AlexandreCamerini/replica}"
ENV_FILE="/nonexistent/.env"   # nada é gravado nem sugerido de .env
LOCAL_URL="${LOCAL_URL:-$("$MAIN/db/pg-local.sh" url)}"
# Ficam no local: dado de usuário (de teste, no local) e estado da própria agenda/migração.
USER_TABLES=(profiles follows digest_deliveries suggestions corrections page_views page_view_hourly)
EXCLUDE=(schema_migrations etl_schedule_attempts "${USER_TABLES[@]}")
# Em produção só estas podem ter linhas antes da carga (o seed escreve as quatro primeiras); são trocadas pelas do local.
SEEDED=(sources offices topics salaries ingest_runs dataset_stamps)
WORK="$(mktemp -d "${TMPDIR:-/tmp}/prod-restore.XXXXXX")"
WAS_ON=""; REENABLED=""
PROD_ENV=()

on_exit() {
  rm -rf "$WORK"
  if [[ -n "$WAS_ON" && -z "$REENABLED" ]]; then
    printf '\n'; warn "a agenda de produção ficou DESLIGADA. Para religar:"
    note "  gh variable set ETL_SCHEDULE_ENABLED --body true --repo $GH_REPO"
  fi
}
trap on_exit EXIT

lpsql() { psql "$LOCAL_URL" -X -q -At -v ON_ERROR_STOP=1 "$@"; }
# rpsql: produção. As PG* só existem no subshell de cada chamada (export é builtin: nada em argv).
rpsql() { ( export "${PROD_ENV[@]}"; exec psql -X -q -At -v ON_ERROR_STOP=1 "$@" ); }
# rq SQL: uma consulta em produção que tem de responder; falha = aborta (nunca "resposta vazia = ok").
rq() { local out; out=$(rpsql -c "$1" 2>&1) || { warn "consulta em produção falhou: $(printf '%s' "$out" | tail -n 1)"; exit 1; }; printf '%s' "$out"; }

# use_prod_url: decompõe a URL (lida da env) em PGHOST/PGPORT/PGUSER/PGPASSWORD/PGDATABASE/PGSSLMODE para PROD_ENV.
use_prod_url() {
  local out line
  out=$(PROD_URL="$1" python3 - <<'PYEOF'
import os
from urllib.parse import urlsplit, unquote, parse_qs
u = urlsplit(os.environ["PROD_URL"])
q = {k: v[-1] for k, v in parse_qs(u.query).items()}
local = u.hostname in ("localhost", "127.0.0.1", "::1")
env = {"PGHOST": u.hostname or "", "PGPORT": str(u.port or 5432), "PGUSER": unquote(u.username or ""),
       "PGPASSWORD": unquote(u.password or ""), "PGDATABASE": unquote(u.path.lstrip("/")) or "postgres",
       "PGSSLMODE": q.get("sslmode", "prefer" if local else "require"),
       "PGCONNECT_TIMEOUT": "15", "PGAPPNAME": "prod-restore"}
assert all("\n" not in v for v in env.values())
print("\n".join(f"{k}={v}" for k, v in env.items()))
PYEOF
) || return 1
  PROD_ENV=()
  while IFS= read -r line; do PROD_ENV+=("$line"); done <<<"$out"
}
prod_get() { local kv; for kv in "${PROD_ENV[@]}"; do [[ "$kv" == "$1="* ]] && { printf '%s' "${kv#*=}"; return; }; done; }

# tables_into SIDE FILE: tabelas base de public, em ordem de byte (comm exige). Falha aborta.
tables_into() {
  local q="select tablename from pg_tables where schemaname = 'public'"
  if [[ "$1" == local ]]; then lpsql -c "$q" >"$2.raw" || { warn "não listei as tabelas do local"; exit 1; }
  else rpsql -c "$q" >"$2.raw" 2>/dev/null || { warn "não listei as tabelas de produção"; exit 1; }; fi
  LC_ALL=C sort "$2.raw" >"$2"
}
migrations_q="select coalesce(string_agg(filename || ':' || sha256, ' ' order by filename), '') from schema_migrations"
in_list() { local x; for x in "${@:2}"; do [[ "$x" == "$1" ]] && return 0; done; return 1; }

# gh_or_die ARGS: chamada ao gh que tem de dar certo.
gh_or_die() { local out; out=$(gh "$@" 2>&1) || { warn "gh $1 $2 falhou: $(printf '%s' "$out" | tail -n 1)"; exit 1; }; printf '%s' "$out"; }

banner "Carga do banco de produção a partir do local"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pré-requisitos"
for b in psql pg_dump pg_restore python3; do command -v "$b" >/dev/null || { warn "falta $b (brew install postgresql@16)"; exit 1; }; done
lpsql -c "select 1" >/dev/null 2>&1 || { warn "Postgres local fora do ar em $LOCAL_URL: $MAIN/db/pg-local.sh start"; exit 1; }
LOCAL_MAJOR=$(( $(lpsql -c "show server_version_num") / 10000 ))
DUMP_MAJOR=$(pg_dump --version | grep -oE '[0-9]+' | head -1)
(( DUMP_MAJOR >= LOCAL_MAJOR )) || { warn "pg_dump $DUMP_MAJOR é mais velho que o Postgres local $LOCAL_MAJOR"; exit 1; }
if [[ -z "${SKIP_GH:-}" ]]; then
  command -v gh >/dev/null || { warn "falta o gh: brew install gh"; exit 1; }
  gh auth status >/dev/null 2>&1 || { warn "gh sem login: rode gh auth login e repita"; exit 1; }
fi
say "Origem: $LOCAL_URL ($(lpsql -c "select pg_size_pretty(pg_database_size(current_database()))"))."
say "Espaço livre para o dump em $WORK: $(df -h "$WORK" | awk 'NR==2{print $4}') (o dump comprimido tem ~1/15 do banco)."
note "A carga sobe pela rede; com o banco de ~5 GB conte de 30 a 90 min."
pause "Enter para seguir"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Pausar a agenda de produção"
if [[ -n "${SKIP_GH:-}" ]]; then
  note "SKIP_GH: agenda do GitHub não consultada"
else
  if [[ "$(gh_or_die variable get ETL_SCHEDULE_ENABLED)" == "true" ]]; then
    say "A agenda do GitHub Actions está ligada: um run-due durante a carga escreveria por cima."
    confirm "Desligar ETL_SCHEDULE_ENABLED até o fim da carga?" || { warn "com a agenda ligada a carga não é segura; parei aqui"; exit 1; }
    WAS_ON=1
    gh_or_die variable set ETL_SCHEDULE_ENABLED --body false >/dev/null
    [[ "$(gh_or_die variable get ETL_SCHEDULE_ENABLED)" == "false" ]] || { warn "a variável não ficou false; parei"; exit 1; }
    printf '  %s✓%s agenda desligada\n' "$GREEN" "$RESET"
  else
    say "Agenda já desligada."
  fi
  # Qualquer execução não concluída (queued, waiting, in_progress...) bloqueia; erro do gh também.
  while RUN=$(gh_or_die run list --workflow etl.yml --limit 20 --json databaseId,status -q '[.[] | select(.status != "completed")][0].databaseId // empty') && [[ -n "$RUN" ]]; do
    warn "há uma execução do ETL não concluída ($RUN)."
    confirm "Esperar ela terminar aqui?" || { warn "parei; rode de novo quando não houver execução"; exit 1; }
    gh run watch "$RUN" >/dev/null 2>&1 || true
  done
fi
pause "Enter para seguir"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Banco de produção"
step "Supabase → projeto → Connect → Session pooler (porta 5432). Troque [YOUR-PASSWORD] pela senha."
note "É a mesma URI do secret ETL_DATABASE_URL."
warn "Disco: a carga escreve ~5 GB de tabelas e índices, mais o WAL. O Pro começa com 8 GB, e o autoscale cresce no máximo"
warn "uma vez a cada 6 h; se encher no meio, o banco entra em modo só leitura e a carga é desfeita."
step "Antes de seguir: Supabase → Project Settings → Compute and Disk → disco em 16 GB (~US$ 1/mês acima dos 8 GB)."
pause "Disco ajustado? Enter para seguir"
while :; do
  ask_secret DB_URL "Cole a URI (entrada oculta):"
  [[ -n "$DB_URL" ]] || { warn "URI vazia; parei aqui"; exit 1; }   # também fim da entrada: sem isso o laço não para
  if [[ ! "$DB_URL" =~ ^postgres(ql)?:// ]]; then warn "não começa com postgres:// ou postgresql://"; continue; fi
  if [[ "$DB_URL" =~ :6543(/|\?|$) || "$DB_URL" == *pgbouncer=true* ]]; then warn "é o Transaction pooler (6543); use o Session pooler"; continue; fi
  if [[ -z "${ALLOW_LOCAL_TARGET:-}" && "$DB_URL" =~ @(localhost|127\.0\.0\.1|\[::1\])[:/] ]]; then warn "é um banco local, não o de produção"; continue; fi
  if [[ "$DB_URL" == *YOUR-PASSWORD* ]]; then warn "ainda tem [YOUR-PASSWORD]; troque pela senha"; continue; fi
  use_prod_url "$DB_URL" || { warn "URI ilegível (senha com / ? # precisa de %-encoding)"; continue; }
  if OUT=$(rpsql -c "select 1" 2>&1); then break; fi
  warn "não conectou:"; note "$(printf '%s' "${OUT//"$DB_URL"/<url>}" | tail -n 2)"
  confirm "Tentar outra URI?" || exit 1
done
unset DB_URL
PGHOST_P=$(prod_get PGHOST)
if [[ "$PGHOST_P" =~ ^(localhost|127\.0\.0\.1|::1)$ && "$(prod_get PGDATABASE):$(prod_get PGPORT)" == "$(lpsql -c "select current_database() || ':' || current_setting('port')")" ]]; then
  warn "destino é o próprio banco de origem"; exit 1
fi
rpsql -c "set session_replication_role = replica" >/dev/null 2>&1 \
  || { warn "este usuário não pode desligar as FKs da sessão (session_replication_role); use o usuário postgres"; exit 1; }
[[ "$(rq "$migrations_q")" == "$(lpsql -c "$migrations_q")" ]] \
  || { warn "migrações diferentes entre local e produção: rode db/migrate.sh nos dois e repita"; exit 1; }
tables_into local "$WORK/t.local"; tables_into remote "$WORK/t.remote"
TABLES=()
while IFS= read -r t; do
  if [[ -n "$t" ]] && ! in_list "$t" "${EXCLUDE[@]}"; then TABLES+=("$t"); fi
done < <(LC_ALL=C comm -12 "$WORK/t.local" "$WORK/t.remote")
if [[ -n "${ONLY_TABLES:-}" ]]; then read -ra TABLES <<<"$ONLY_TABLES"; fi
(( ${#TABLES[@]} )) || { warn "nenhuma tabela em comum para carregar"; exit 1; }
ONLY_LOCAL=$(LC_ALL=C comm -23 "$WORK/t.local" "$WORK/t.remote" | tr '\n' ' ')
[[ -z "${ONLY_LOCAL// /}" ]] || note "só existem no local (ficam de fora): $ONLY_LOCAL"
# Vazio = toda tabela carregada fora do seed, e toda tabela de usuário (o delete do seed roda sem disparar FKs).
MUST_BE_EMPTY=()
for t in "${TABLES[@]}"; do if ! in_list "$t" "${SEEDED[@]}"; then MUST_BE_EMPTY+=("$t"); fi; done
for t in "${USER_TABLES[@]}"; do if grep -qx "$t" "$WORK/t.remote"; then MUST_BE_EMPTY+=("$t"); fi; done
(( ${#MUST_BE_EMPTY[@]} )) || MUST_BE_EMPTY=(sources)   # bash 3.2 + set -u não aceita array vazio; sources está sempre lá
DIRTY=()
for t in "${MUST_BE_EMPTY[@]}"; do
  if in_list "$t" "${SEEDED[@]}"; then continue; fi
  r=$(rq "select exists (select 1 from public.\"$t\")")
  case "$r" in t) DIRTY+=("$t") ;; f) ;; *) warn "resposta inesperada para $t: $r"; exit 1 ;; esac
done
if (( ${#DIRTY[@]} )); then
  warn "produção já tem dados fora do seed: ${DIRTY[*]}"
  say "O ETL (ou alguém) já escreveu lá. Esta carga só roda num banco vazio, para não misturar ids."
  exit 1
fi
say "Produção vazia (salvo o seed), migrações iguais, ${#TABLES[@]} tabelas a carregar."
pause "Enter para gerar o dump local"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Dump do local"
# Uma sessão segura um snapshot: as contagens e o pg_dump enxergam o mesmo instante, mesmo com o ETL local rodando.
# (FIFOs em vez de coproc: o bash do macOS é o 3.2.)
mkfifo "$WORK/snap.in" "$WORK/snap.out"
psql "$LOCAL_URL" -X -q -At -v ON_ERROR_STOP=1 <"$WORK/snap.in" >"$WORK/snap.out" 2>"$WORK/snap.err" &
SNAP_PID=$!
exec 3>"$WORK/snap.in" 4<"$WORK/snap.out"
snap_fail() { warn "sessão do snapshot caiu: $(cat "$WORK/snap.err" 2>/dev/null)"; exit 1; }
printf 'begin isolation level repeatable read;\nselect pg_export_snapshot();\n' >&3 || snap_fail
read -r SNAP <&4 || snap_fail
: >"$WORK/counts.local"
for t in "${TABLES[@]}"; do
  printf "select '%s', count(*) from public.\"%s\";\n" "$t" "$t" >&3 || snap_fail
  read -r line <&4 || snap_fail
  printf '%s\n' "$line" >>"$WORK/counts.local"
done
TARGS=(); for t in "${TABLES[@]}"; do TARGS+=(-t "public.\"$t\""); done
say "Gerando o dump (snapshot $SNAP)..."
note "O aviso do pg_dump sobre FK circular (places) é esperado: a carga roda com as FKs da sessão desligadas."
SECONDS=0
pg_dump "$LOCAL_URL" --snapshot="$SNAP" --data-only --no-owner --no-privileges -Fc -Z 6 "${TARGS[@]}" -f "$WORK/data.dump"
printf 'commit;\n' >&3; exec 3>&- 4<&-; wait "$SNAP_PID" 2>/dev/null || true
say "Dump: $(du -h "$WORK/data.dump" | cut -f1) em ${SECONDS}s, $(awk -F'|' '{s+=$2} END {print s}' "$WORK/counts.local") linhas."
pause "Enter para seguir"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Carga em produção"
say "Numa transação: trava as ${#TABLES[@]} tabelas, confere de novo que estão vazias, troca o seed (${SEEDED[*]}),"
say "carrega com as FKs da sessão desligadas e, antes do COMMIT, confere contagens e FKs órfãs."
say "Se algo falhar (ou Ctrl-C, ou a conexão cair), o COMMIT não é enviado e o banco desfaz tudo."
confirm "Carregar os dados no banco de PRODUÇÃO ($PGHOST_P) agora?" || { warn "nada foi gravado"; exit 1; }
qlist() { local t out=""; for t in "$@"; do out+="${out:+, }public.\"$t\""; done; printf '%s' "$out"; }
# O pg_restore zera o search_path: daqui em diante todo nome vai qualificado.
pre_sql() {
  printf 'begin;\nset statement_timeout = 0;\nset session_replication_role = replica;\n'
  printf 'lock table %s in access exclusive mode;\n' "$(qlist "${TABLES[@]}")"
  printf "do \$\$ declare t text; e boolean; begin foreach t in array array[%s]::text[] loop\n" "$(printf "'%s'," "${MUST_BE_EMPTY[@]}" | sed 's/,$//')"
  printf "  if exists (select 1 from pg_catalog.pg_tables where schemaname = 'public' and tablename = t) then\n"
  printf "    execute pg_catalog.format('select exists (select 1 from public.%%I)', t) into e;  -- EXECUTE não mexe em FOUND
    if e and t <> all (array[%s]::text[]) then raise exception 'produção deixou de estar vazia: %%', t; end if;\n" "$(printf "'%s'," "${SEEDED[@]}" | sed 's/,$//')"
  printf "  end if; end loop; end \$\$;\n"
  for t in "${SEEDED[@]}"; do if in_list "$t" "${TABLES[@]}"; then printf 'delete from public."%s";\n' "$t"; fi; done
}
post_sql() {
  printf "do \$\$ declare r record; c bigint; bad text := ''; begin\n"
  printf "  for r in select * from (values %s) v(t, n) loop\n" "$(awk -F'|' '{printf "%s(%c%s%c, %s)", (NR>1?", ":""), 39, $1, 39, $2}' "$WORK/counts.local")"
  printf "    execute pg_catalog.format('select count(*) from public.%%I', r.t) into c;\n"
  printf "    if c <> r.n then bad := bad || pg_catalog.format('%%s: local %%s, produção %%s; ', r.t, r.n, c); end if;\n"
  printf "  end loop;\n  if bad <> '' then raise exception 'contagens diferentes: %%', bad; end if; end \$\$;\n"
  cat <<'SQLEOF'
do $$
declare r record; n bigint; bad text := '';
begin
  for r in
    select k.conrelid::regclass c, k.confrelid::regclass p, a.attname ca, b.attname pa
    from pg_catalog.pg_constraint k
    join pg_catalog.pg_attribute a on a.attrelid = k.conrelid and a.attnum = k.conkey[1]
    join pg_catalog.pg_attribute b on b.attrelid = k.confrelid and b.attnum = k.confkey[1]
    where k.contype = 'f' and pg_catalog.cardinality(k.conkey) = 1 and k.connamespace = 'public'::regnamespace
  loop
    execute pg_catalog.format('select count(*) from %s x where x.%I is not null and not exists (select 1 from %s y where y.%I = x.%I)', r.c, r.ca, r.p, r.pa, r.ca) into n;
    if n > 0 then bad := bad || pg_catalog.format('%s.%s → %s: %s; ', r.c, r.ca, r.p, n); end if;
  end loop;
  if bad <> '' then raise exception 'FK órfã: %', bad; end if;
end $$;
SQLEOF
  printf 'commit;\n'
}
SECONDS=0
# COMMIT só sai se o pg_restore terminou com 0 (&&); sem ele o psql chega ao fim com a transação aberta e o servidor desfaz.
if ! { pre_sql; pg_restore --data-only --no-owner --no-privileges -f - "$WORK/data.dump" && post_sql; } | rpsql -f - >/dev/null; then
  warn "a carga falhou (erro acima). O COMMIT não foi enviado ou foi recusado: o banco desfez a transação."
  note "Se a conexão caiu durante o próprio COMMIT, o estado é incerto: rode o assistente de novo, ele confere se produção está vazia."
  exit 1
fi
say "Carregado e conferido (contagens e FKs) em $((SECONDS / 60)) min."
pause "Enter para seguir"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Estatísticas, invariantes e agenda"
say "Atualizando estatísticas (vacuum analyze)..."
for t in "${TABLES[@]}"; do
  rpsql -c "set statement_timeout = 0" -c "vacuum (analyze) public.\"$t\"" >/dev/null 2>&1 || warn "vacuum de $t falhou (os dados estão gravados; o autovacuum cobre)"
done
if [[ -x "$PY" ]] && confirm "Rodar as invariantes do ETL (civico_etl check) em produção?"; then
  ( export "${PROD_ENV[@]}"; cd "$ROOT/etl" && ETL_DATABASE_URL="postgres://" exec "$PY" -m civico_etl.cli check ) && say "Invariantes ok." \
    || warn "invariantes quebradas: veja acima (os dados entraram; a agenda corrige o que for carga vencida)"
fi
if [[ -n "$WAS_ON" ]] && confirm "Religar a agenda (ETL_SCHEDULE_ENABLED=true)?"; then
  gh_or_die variable set ETL_SCHEDULE_ENABLED --body true >/dev/null && REENABLED=1
  printf '  %s✓%s agenda religada\n' "$GREEN" "$RESET"
fi

finish
